    /** Turns the sails about the masts (degrees): 0 is across the ship, as with the wind from astern. */
    public void setSailAngle(float degrees) {
        for (ModelPart sail : sails) {
            sail.yRot = Trig.toRadians(degrees);
        }
    }

    /** Swings the oars by the rowing phase (degrees): the blades go forward in the air and back in the water. */
    public void setOarPhase(float degrees) {
        float swing = 0.5F * Trig.sin(Trig.toRadians(degrees));
        float lift = 0.2F * Trig.cos(Trig.toRadians(degrees));
        for (ModelPart oar : oarsStarboard) {
            oar.yRot = swing;
            oar.zRot = -(0.3F + lift);
        }
        for (ModelPart oar : oarsPort) {
            oar.yRot = -swing;
            oar.zRot = 0.3F + lift;
        }
    }

    /** Points a turret mount: {@code yaw} degrees from the bow (a vehicle yaw), {@code pitch} the elevation, {@code recoil} 0 to 1. */
    public void setHardpoint(int index, float yaw, float pitch, float recoil) {
        if (index < hardpointYaw.length) {
            hardpointYaw[index].yRot = Trig.toRadians(-yaw);
            hardpointPitch[index].xRot = Trig.toRadians(-pitch);
            hardpointPitch[index].z = recoil * 4.0F;
        }
    }
